// Builds RESULTS.md from the raw evidence only (evidence/benchmark-*.json and
// evidence/runs/**). Nothing here is typed by hand: re-run the benchmarks and
// this script, and the report regenerates. Usage: npm run report
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { DOMAINS } from "../src/domains/index.ts";

const fmt = (n: number) => n.toLocaleString("en-US");
const out: string[] = [
  "# ZeroBleed results report",
  "",
  "Generated by `npm run report` from the raw files in [`evidence/`](evidence/). Every number below is computed from those files; nothing is typed by hand.",
  "",
  "## How to check these results are real",
  "",
  "1. **Model calls.** Each run has a `*.calls.json` file listing every model call with the model name, the token usage Nightshift reported, and the Nightshift **receipt ID**. Open Nightshift's **Receipts** view and look up any receipt ID: it shows the same request, model and token counts. Our code cannot write to that view.",
  "2. **Data.** Each fact a decision used is listed with the exact Zetaris SQL that produced it (`evidence` in `*.calls.json`). Run the same SQL in the Zetaris SQL Editor at http://localhost:3000 and you get the same value.",
  "3. **Steps.** Each run has a `*.trace.jsonl` file: one line per planner, worker, gate, guard, Markovian chunk and decision, with timestamps and models.",
  "4. **Reproduce.** `npm run benchmark -- procurement 1` and `npm run benchmark -- incident 1`, then `npm run report`. Models can vary slightly between runs; the correct answers are fixed in `src/domains/*.ts`.",
  "",
  "Failures stay in the denominator. Token counts are input tokens as reported by Nightshift, which include Nightshift's own per-request overhead for both systems alike.",
  "",
];

for (const d of Object.values(DOMAINS)) {
  const file = `evidence/benchmark-${d.id}.json`;
  if (!existsSync(file)) continue;
  const { summary, rows } = JSON.parse(readFileSync(file, "utf8"));
  const saved = 100 * (1 - summary.zerobleed.inputTokens / Math.max(1, summary.baseline.inputTokens));
  out.push(
    `## ${d.title}`,
    "",
    `Measured ${summary.date.slice(0, 10)} on ${summary.machine}. Fast lane \`${summary.models.fast}\`, deep lane \`${summary.models.deep}\`. ${rows.length} runs.`,
    "",
    "| | ZeroBleed | Shared-history agent |",
    "|---|---|---|",
    `| Correct decisions | **${summary.zerobleed.correct} / ${rows.length}** | ${summary.baseline.correct} / ${rows.length} |`,
    `| Input tokens, total | **${fmt(summary.zerobleed.inputTokens)}** | ${fmt(summary.baseline.inputTokens)} |`,
    `| Largest single prompt | **${fmt(summary.zerobleed.largestCallInput ?? 0)}** | ${fmt(summary.baseline.largestCallInput ?? 0)} |`,
    `| Median wall time per case | ${summary.zerobleed.medianSeconds ?? "-"}s | ${summary.baseline.medianSeconds ?? "-"}s |`,
    "",
    `ZeroBleed read **${saved.toFixed(1)}% fewer input tokens**.`,
    "",
    "| Run | Scenario | Expected | ZeroBleed | Shared-history agent | Evidence |",
    "|---|---|---|---|---|---|",
  );
  for (const r of rows) {
    const c = d.cases.find((x) => x.id === r.case)!;
    const runId = `${r.case}-r${r.run}`;
    const dir = `evidence/runs/${d.id}`;
    const ev = existsSync(`${dir}/${runId}.calls.json`) ? `[calls](${dir}/${runId}.calls.json) · [trace](${dir}/${runId}.trace.jsonl)` : "summary only";
    const mark = (ok: boolean) => (ok ? "✅" : "❌");
    out.push(
      `| ${runId} | ${r.scenario} | ${c.expect} ${c.value} | ${mark(r.zerobleed.correct)} ${r.zerobleed.decision} ${r.zerobleed.value ?? r.zerobleed.penalty ?? ""} · ${fmt(r.zerobleed.inputTokens)} tok | ${mark(r.baseline.correct)} ${r.baseline.decision ?? "none"} ${r.baseline.value ?? r.baseline.penalty ?? ""} · ${fmt(r.baseline.inputTokens)} tok | ${ev} |`
    );
  }
  out.push("");
  // A sample of receipts so a reader can spot-check without opening files.
  const dir = `evidence/runs/${d.id}`;
  if (existsSync(dir)) {
    const first = readdirSync(dir).find((f) => f.endsWith(".calls.json"));
    if (first) {
      const calls = JSON.parse(readFileSync(`${dir}/${first}`, "utf8"));
      out.push(`Receipts from \`${first}\` (look these up in Nightshift > Receipts):`, "", "| Step | Model | Input tokens | Nightshift receipt |", "|---|---|---|---|");
      for (const e of calls.zerobleed.calls) out.push(`| ZeroBleed ${e.task} | ${e.model} | ${fmt(e.inputTokens)} | \`${e.receiptId ?? "n/a"}\` |`);
      for (const t of calls.baseline.calls) out.push(`| Baseline ${t.turn} | ${t.model ?? "-"} | ${fmt(t.inputTokens)} | \`${t.receiptId ?? "n/a"}\` |`);
      out.push("");
    }
  }
}

out.push(
  "## Markovian engine conformance",
  "",
  "```",
  existsSync("evidence/markovian-conformance.txt") ? readFileSync("evidence/markovian-conformance.txt", "utf8").trim() : "not run",
  "```",
  ""
);
writeFileSync("RESULTS.md", out.join("\n"));
console.log("wrote RESULTS.md");
